class Session:
    def __init__(self, load): self.load, self.cache = load, {}
    def get(self, id):
        if id not in self.cache:
            self.cache[id] = self.load(id)
        return self.cache[id]

using System;
using System.Collections.Generic;
public sealed class Session(Func<int,object> load) {
    readonly Dictionary<int,object> cache = new();
    public object Get(int id) {
        if (!cache.TryGetValue(id,out var value)) {
            value=load(id);
            cache.Add(id,value);
        }
        return value;
    }
}

class Holder:
    def __init__(self, load):
        self.load, self.loaded, self.value = load, False, 0
    def get(self):
        if not self.loaded:
            value = self.load()
            self.value, self.loaded = value, True
        return self.value

using System;
public sealed class Holder(Func<int> load) {
    bool loaded;
    int value;
    public int Get() {
        if (!loaded) {
            int result=load();
            value=result;
            loaded=true;
        }
        return value;
    }
}

