import MaybeValue.*

object MonadExample {
  def half(x: Int): Value[Int] =
    if (x % 2 == 0) some(x / 2) else none()
  def run(x: Int): Value[Int] = some(x).bind(half).bind(half)
}

object MaybeValue {
  enum Value[+A] {
    case Absent extends Value[Nothing]
    case Present(value: A)
    def bind[B](next: A => Value[B]): Value[B] = this match {
      case Absent => Absent
      case Present(value) => next(value)
    }
  }
  def some[A](value: A): Value[A] = Value.Present(value)
  def none[A](): Value[A] = Value.Absent
}

import Bounce.*

object TrampolineExample {
  def evenStep(n: Int): Value[Boolean] =
    if (n == 0) done(true) else more(() => oddStep(n - 1))
  def oddStep(n: Int): Value[Boolean] =
    if (n == 0) done(false) else more(() => evenStep(n - 1))
  def parity(n: Int): Boolean = run(evenStep(n))
}

object Bounce {
  enum Value[+A] {
    case Done(answer: A)
    case More(next: () => Value[A])
  }
  def done[A](answer: A): Value[A] = Value.Done(answer)
  def more[A](next: () => Value[A]): Value[A] = Value.More(next)
  @annotation.tailrec
  def run[A](current: Value[A]): A = current match {
    case Value.Done(answer) => answer
    case Value.More(next) => run(next())
  }
}

import Around.bracket

object ExecuteAroundExample {
  final case class Resource(value: Int)
  final class ResourceFailure extends RuntimeException
  def run(mode: Int): Int = {
    var events = 0
    def note(n: Int): Unit = { events = events * 10 + n }
    try {
      val value = bracket(
        () => {
          note(1)
          if (mode == 2) throw new ResourceFailure
          Resource(42)
        },
        (_: Resource) => note(3),
        (resource: Resource) => {
          note(2)
          if (mode == 1) throw new ResourceFailure
          resource.value
        })
      value * 1000 + events
    } catch {
      case _: ResourceFailure => -events
    }
  }
}

